effect.shader:
// O fundo (a cena montada atrás da camada) no pixel da tela, pré-multiplicado (o do Anel).
vec3 fundoNoPixel() {
    ivec2 T = textureSize(comp, 0);
    ivec2 px = clamp(ivec2(floor(acTela(acScreenNorm) * vec2(T))), ivec2(0), T - 1);
    vec4 f = texelFetch(comp, px, 0);
    return f.rgb * f.a;
}

// A saída pré-multiplicada do AM (`q`, já em 8 bits) em cor reta — a do `am-sharpen.xml`: onde a cor passa do alfa, o
// menor alfa em que a cor reta cabe, com o fundo junto, dá na composição Normal o mesmo que a soma do AM.
vec4 paraReta(vec4 q) {
    if (all(lessThanEqual(q.rgb, vec3(q.a)))) return q.a > 0.0 ? vec4(q.rgb / q.a, q.a) : vec4(0.0);
    vec3 d = fundoNoPixel();
    vec3 sobra = q.rgb - d * q.a;
    vec3 folga = 1.0 - d;
    float a = q.a;
    for (int i = 0; i < 3; i++) {
        if (sobra[i] > 0.0 && folga[i] > 0.0) a = max(a, sobra[i] / folga[i]);
    }
    a = min(a, 1.0);
    return a > 0.0 ? vec4(clamp(d + sobra / a, 0.0, 1.0), a) : vec4(0.0);
}

// k ÷ 255 com o arredondamento certo: o float EXATO que a textura de 8 bits devolve ao AM (ver `am-color-balance.xml`).
float oitoBits(float k) {
    uint n = uint(k);
    if (n == 0u) return 0.0;
    if (n == 255u) return 1.0;
    int j = 0;                                                    // o bit mais alto de n
    for (int i = 1; i < 8; i++) if (n >= (1u << uint(i))) j = i;
    int e = 31 - j;
    uint q = ((n << uint(e)) + 127u) / 255u;                      // entre 2^23 e 2^24
    return uintBitsToFloat((uint(150 - e) << 23) + (q - 0x800000u));
}

// Daqui até o fim do passe 0, o shader do AM com os nomes dele, na mesma ordem e na mesma precisão.
mediump vec3 hsv2rgb(mediump vec3 c)
{
    mediump vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    mediump vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);

const highp mat3 rgb2yuv = mat3(
     0.299,     0.587,    0.114,
    -0.14713,  -0.28886,  0.436,
     0.615,    -0.51499, -0.10001
);

const highp mat3 yuv2rgb = mat3(
    1.0,  0.0,      1.13983,
    1.0, -0.39465, -0.58060,
    1.0,  2.03211,  0.0
);

void main() {
    if (acPass == 0) {
        // A camada do AM chega pré-multiplicada EM 8 BITS, pelo mais perto (o premul do Android). No opaco a cor já é
        // o float da textura, bit a bit.
        vec4 c = texture(inputImg, acScreenNorm);
        vec3 pre = c.rgb;
        if (c.a < 1.0) {
            vec3 k = floor(c.rgb * c.a * 255.0 + 0.5);
            pre = vec3(oitoBits(k.r), oitoBits(k.g), oitoBits(k.b));
        }
        // Os parâmetros no `mediump` dos uniforms do AM.
        mediump vec3 cor = color;
        mediump vec3 tom = tint;

        mediump vec4 source = vec4(pre, c.a);
        mediump float luminance = dot(source.rgb, luminanceWeighting);

        mediump float gamma = cor.z+1.0;
        luminance = pow(luminance,1.0/gamma);

        mediump float hue = cor.x /360.;
        mediump float sat = cor.y;
        mediump float hue2 = tom.x /360.;
        mediump float sat2 = tom.y;

        mediump vec3 darkColor =  hsv2rgb(vec3(hue,sat,1.0));
        mediump vec3 baseColor =  hsv2rgb(vec3(hue,sat,1.0));
        mediump vec3 lightColor =  hsv2rgb(vec3(hue2,sat2,1.0));

        mediump float cutoff = tom.z / 2.0 + 0.5;
        mediump vec3 blendColor = luminance < cutoff ? mix( darkColor, baseColor, luminance/cutoff) :  mix( baseColor, lightColor, (luminance-cutoff)/(1.-cutoff));

        mediump vec3 yuv = blendColor * rgb2yuv;
        yuv.x = luminance;
        yuv.yz *= luminance;
        blendColor = yuv * yuv2rgb;

        mediump float shineStart = .85;
        mediump float shineAmount = max(0.,luminance - shineStart) * (1./(1.-shineStart));
        shineAmount = shineAmount * shineAmount * sat;
        blendColor = mix( blendColor, vec3(1.), shineAmount );

        // O corte em 0..1 é o do alvo de 8 bits do AM; escrito aqui para o projeto de 32 bits sair igual.
        fragColor = clamp(vec4(blendColor,1.0) * source.a, 0.0, 1.0);
        return;
    }
    fragColor = paraReta(texture(quente, acScreenNorm));
}
